type NodeOpen struct {
	Session            *Session
	StaticPublicKey    string
	EphemeralPublicKey string
}

func StaticSlot(deviceId string) string {
	return staticSlot(deviceId)
}

func StaticPublic(deviceId string) witTypes.Result[string, string] {
	if err := validateText(deviceId, "device id"); err != nil {
		return witTypes.Err[string, string](err.Error())
	}
	key, err := ensureStaticKey(deviceId)
	if err != nil {
		return witTypes.Err[string, string](err.Error())
	}
	defer key.Drop()
	publicKey, err := publicText(key)
	if err != nil {
		return witTypes.Err[string, string](err.Error())
	}
	return witTypes.Ok[string, string](publicKey)
}

func OpenNode(deviceId string, clientId string, challenge string, clientPublicKey string) witTypes.Result[NodeOpen, string] {
	nodeOpen, err := openNode(deviceId, clientId, challenge, clientPublicKey)
	if err != nil {
		return witTypes.Err[NodeOpen, string](err.Error())
	}
	return witTypes.Ok[NodeOpen, string](nodeOpen)
}

func Encrypt(session *Session, direction uint8, sequence uint64, sessionId string, label string, plaintext []uint8) witTypes.Result[string, string] {
	ciphertext := session.key.Encrypt(
		frameNonce(direction, sequence),
		frameAAD(sessionId, sequence, label),
		plaintext,
	)
	if ciphertext.IsErr() {
		return witTypes.Err[string, string](ciphertext.Err())
	}
	return witTypes.Ok[string, string](base64.RawURLEncoding.EncodeToString(ciphertext.Ok()))
}

func Decrypt(session *Session, direction uint8, sequence uint64, sessionId string, label string, ciphertext string) witTypes.Result[[]uint8, string] {
	encoded, err := base64.RawURLEncoding.DecodeString(ciphertext)
	if err != nil {
		return witTypes.Err[[]uint8, string]("invalid control ciphertext encoding")
	}
	plaintext := session.key.Decrypt(
		frameNonce(direction, sequence),
		frameAAD(sessionId, sequence, label),
		encoded,
	)
	if plaintext.IsErr() {
		return witTypes.Err[[]uint8, string](plaintext.Err())
	}
	return witTypes.Ok[[]uint8, string](plaintext.Ok())
}
